import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"빠른 시작","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/getting-started.md","filePath":"ko-KR/user-guide/getting-started.md","lastUpdated":1787982919000}'),l={name:"ko-KR/user-guide/getting-started.md"};function d(n,t,i,s,c,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="빠른-시작" tabindex="-1">빠른 시작 <a class="header-anchor" href="#빠른-시작" aria-label="Permalink to &quot;빠른 시작&quot;">​</a></h1><p>Lertaro에 오신 것을 환영합니다! Lertaro는 Windows 환경에 최적화된 초고속 파일 검색기 및 생산성 런처입니다. 이 가이드에서는 설치 방법, 핵심 아키텍처, 3가지 윈도우 모드 및 기본적인 검색 워크플로를 안내합니다.</p><h2 id="_1-다운로드-및-설치" tabindex="-1">1. 다운로드 및 설치 <a class="header-anchor" href="#_1-다운로드-및-설치" aria-label="Permalink to &quot;1. 다운로드 및 설치&quot;">​</a></h2><p>공식 홈페이지에서 최신 릴리스를 다운로드할 수 있습니다. 각 배포 버전은 네이티브 <strong>x64</strong> 및 <strong>ARM64</strong> 애플리케이션용 설치 프로그램과 포터블 패키지로 제공됩니다.</p><h3 id="설치-프로그램-lertaro-setup-exe-권장" tabindex="-1">설치 프로그램 (<code>Lertaro-Setup.exe</code>, 권장) <a class="header-anchor" href="#설치-프로그램-lertaro-setup-exe-권장" aria-label="Permalink to &quot;설치 프로그램 (`Lertaro-Setup.exe`, 권장)&quot;">​</a></h3><ul><li><strong>자동 구성</strong>: 설치 마법사가 백그라운드 인덱싱 서비스(<code>Lertaro.Service</code>)를 자동 등록하고, 시작 프로그램에 추가하며, 필요한 .NET 데스크톱 런타임을 자동으로 감지하여 설치합니다.</li><li><strong>원활한 업데이트</strong>: 백그라운드 자동 업데이트 확인 및 원클릭 덮어쓰기 업그레이드를 지원합니다.</li></ul><h3 id="포터블-버전-lertaro-portable-zip" tabindex="-1">포터블 버전 (<code>Lertaro-Portable.zip</code>) <a class="header-anchor" href="#포터블-버전-lertaro-portable-zip" aria-label="Permalink to &quot;포터블 버전 (`Lertaro-Portable.zip`)&quot;">​</a></h3><ul><li><strong>무설치 압축 해제 실행</strong>: 원하는 폴더에 압축을 풀고 즉시 실행할 수 있습니다.</li><li><strong>런타임 의존성</strong>: 시스템에 필요한 .NET 데스크톱 런타임이 없는 경우, 압축 해제 디렉토리에 포함된 <code>install-dotnet-runtime.bat</code> 스크립트를 실행하여 설치할 수 있습니다.</li><li><strong>독립적인 데이터 저장</strong>: 포터블 버전은 프로그램과 동일한 디렉토리의 <code>Data\\Machine</code>에 머신 데이터를, <code>Data\\Users\\&lt;SID hash&gt;</code>에 사용자 설정을 저장합니다. <code>Data</code> 폴더가 아직 없는 경우 호환성을 위해 시스템의 <code>%ProgramData%\\Lertaro</code> 및 <code>%LocalAppData%\\Lertaro</code>를 읽어오며, 폴더가 생성되면 완전히 독립된 자급자족 포터블 환경으로 동작합니다.</li><li><strong>클린 제거</strong>: 포터블 폴더를 삭제하기 전에 포함된 <code>portable-cleanup.bat</code> 스크립트를 실행하세요. 백그라운드 서비스를 중지 및 제거하고, 사용자의 <code>lertaro://</code> URI 프로토콜 및 시작 프로그램 레지스트리 항목을 깔끔하게 정리합니다.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Surface Pro X나 스냅드래곤 탑재 노트북과 같은 Windows on ARM 기기에서는 네이티브 <code>Lertaro-Setup-arm64.exe</code> 또는 <code>Lertaro-Portable-arm64.zip</code>을 다운로드하여 최고의 성능과 배터리 효율을 경험하세요.</p></div><h2 id="_2-핵심-아키텍처-개요" tabindex="-1">2. 핵심 아키텍처 개요 <a class="header-anchor" href="#_2-핵심-아키텍처-개요" aria-label="Permalink to &quot;2. 핵심 아키텍처 개요&quot;">​</a></h2><p>Lertaro를 처음 실행하면 독립적인 Windows 백그라운드 서비스(<code>Lertaro.Service</code>)가 설치되고 실행됩니다. 이 구조를 이해하면 Lertaro를 더욱 효율적으로 활용할 수 있습니다.</p><ul><li><strong>포그라운드 App (UI 및 인터랙션)</strong>: 검색창, 플로팅 패널, 액션 메뉴, 키보드 후킹 및 즉시 미리보기 렌더링을 담당합니다. 메모리 점유율을 최소화하고 즉각적인 반응 속도를 유지합니다.</li><li><strong>백그라운드 Service (인덱싱 및 데이터)</strong>: 서비스 권한으로 백그라운드에 상주하며, NTFS / ReFS USN 변경 저널 모니터링, 기타 파일 시스템의 실시간 변경 감지, 네트워크 공유 인덱스 관리 및 인메모리 검색 트리를 유지 관리합니다.</li><li><strong>아키텍처의 장점</strong>: UI를 재시작하거나 업데이트해도 백그라운드 인덱스가 손실되거나 전체 디스크를 다시 스캔하지 않습니다. 또한 대규모 인덱싱 작업이 UI의 매끄러운 타이핑을 방해하지 않습니다. <a href="./settings/service-status.html"><strong>설정 → 서비스 상태</strong></a>에서 언제든지 상태를 확인할 수 있습니다.</li></ul><h2 id="_3-세-가지-윈도우-모드" tabindex="-1">3. 세 가지 윈도우 모드 <a class="header-anchor" href="#_3-세-가지-윈도우-모드" aria-label="Permalink to &quot;3. 세 가지 윈도우 모드&quot;">​</a></h2><p>Lertaro는 고정된 단일 창에 국한되지 않고 다양한 워크플로에 맞춘 세 가지 윈도우 모드를 제공합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">윈도우 모드</th><th style="text-align:left;">기본 호출 방법</th><th style="text-align:left;">주요 특징 및 설계 콘셉트</th><th style="text-align:left;">최적의 활용 시나리오</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>퀵 윈도우 (Quick Window)</strong></td><td style="text-align:left;"><code>Ctrl</code> 더블 클릭 (사용자 지정 가능)</td><td style="text-align:left;">화면 중앙에 빠르게 나타나는 컴팩트 플로팅 창. 숫자키 빠른 이동 및 키보드 중심 조작에 최적화</td><td style="text-align:left;">자주 쓰는 앱 실행, 특정 파일 즉시 검색, 빠른 계산 및 번역</td></tr><tr><td style="text-align:left;"><strong>메인 윈도우 (Full Window)</strong></td><td style="text-align:left;">작업 표시줄/시작 메뉴, 또는 <code>Ctrl+F</code></td><td style="text-align:left;">대화면 풀 기능 창. 대량 결과 테이블 뷰, 사이드바 필터 그룹, 열 정렬, 내장 공간 분석기 지원</td><td style="text-align:left;">심층 파일 탐색, 광범위한 검색, 디스크 공간 정리 및 상세 필터링</td></tr><tr><td style="text-align:left;"><strong>인라인 윈도우 (Inline Window)</strong></td><td style="text-align:left;">파일 대화상자 또는 탐색기 열기 시 자동 임베드</td><td style="text-align:left;">Windows 표준 파일 대화상자 및 지원되는 파일 관리자에 원활하게 내장되어 작업 컨텍스트를 벗어나지 않고 검색</td><td style="text-align:left;">앱에서 &quot;열기&quot; 또는 &quot;다른 이름으로 저장&quot; 시 대상 폴더/파일을 빠르게 지정</td></tr></tbody></table><p>세 가지 창 모드는 완전히 동일한 검색 엔진, 단축키 체계, 필터 규칙 및 액션 메뉴를 공유합니다.</p><h2 id="_4-첫-검색-및-기본-조작" tabindex="-1">4. 첫 검색 및 기본 조작 <a class="header-anchor" href="#_4-첫-검색-및-기본-조작" aria-label="Permalink to &quot;4. 첫 검색 및 기본 조작&quot;">​</a></h2><h3 id="입력하여-즉시-검색" tabindex="-1">입력하여 즉시 검색 <a class="header-anchor" href="#입력하여-즉시-검색" aria-label="Permalink to &quot;입력하여 즉시 검색&quot;">​</a></h3><p>검색창을 열고 원하는 단어를 입력하기만 하면 결과가 실시간(밀리초 단위)으로 나타납니다. 검색 알고리즘은 기본적으로 퍼지(Fuzzy) 매칭을 사용하므로, 문자가 연속되지 않고 띄엄띄엄 있어도 정확히 찾아냅니다. 상세 문법은 <a href="./search-syntax.html"><strong>검색 문법</strong></a>을 참고하세요.</p><h3 id="결과-이동-및-실행" tabindex="-1">결과 이동 및 실행 <a class="header-anchor" href="#결과-이동-및-실행" aria-label="Permalink to &quot;결과 이동 및 실행&quot;">​</a></h3><ul><li><strong>선택 항목 이동</strong>: 방향키 <code>↑</code> / <code>↓</code>(또는 설정된 탐색 단축키 <code>Ctrl+P</code> / <code>Ctrl+N</code>)를 사용하여 목록을 이동합니다.</li><li><strong>직접 열기</strong>: <code>Enter</code>를 눌러 선택한 파일을 열거나 응용 프로그램을 실행합니다.</li><li><strong>탐색기에서 위치 확인</strong>: <code>Ctrl+Enter</code>를 누르면 파일 탐색기가 열리고 해당 파일이 선택된 상태로 표시됩니다.</li><li><strong>관리자 권한으로 실행</strong>: <code>Ctrl+Shift+Enter</code>를 눌러 관리자 권한으로 실행합니다.</li><li><strong>숫자키 빠른 실행</strong>: 퀵 윈도우에서는 <code>Ctrl</code> + <code>1</code>–<code>9</code>를 눌러 상위 9개 결과를 즉시 열 수 있습니다.</li></ul><h3 id="액션-메뉴-및-확장-조작" tabindex="-1">액션 메뉴 및 확장 조작 <a class="header-anchor" href="#액션-메뉴-및-확장-조작" aria-label="Permalink to &quot;액션 메뉴 및 확장 조작&quot;">​</a></h3><p>선택한 항목에서 <code>Ctrl+O</code> 또는 방향키 <code>→</code>를 누르면 강력한 <strong>액션 메뉴</strong>가 열리며, 경로 복사, 속성 확인, 파일 조작, 플러그인 확장 기능 등을 실행할 수 있습니다. 자세한 내용은 <a href="./actions-and-preview.html"><strong>액션 및 미리보기</strong></a>와 <a href="./hotkeys.html"><strong>단축키</strong></a>를 참조하세요.</p>',23)])])}const p=e(l,[["render",d]]);export{u as __pageData,p as default};
